        t = run_text(r)
        L = len(t)
        if L == 0:
            continue
        if off == pos:
            return r
        if off < pos < off + L:
            k = pos - off
            new = copy.deepcopy(r)
            _set_t(r, t[:k]); _set_t(new, t[k:])
            r.addnext(new)
